"""바룩 타일 — 무무 타일 시스템(포르투 방식)의 규칙으로 그린 서류 도구 묶음.
96×96 판, 8px 칸. 면만 쓴다(외곽선·그러데이션·그림자·글자 없음). 색은 무무 팔레트의 만들기 무리만.
실행: python3 docs/tiles_baruch.py  →  docs/tiles/b-NN.svg, docs/tiles.svg(스프라이트)"""
import os, re
HERE = os.path.dirname(os.path.abspath(__file__))
BG, D, M, L, Pa = '#F7F2E6', '#2C6349', '#43825E', '#8FCB77', '#BEE0AA'
PAL = {BG, D, M, L, Pa}
def R(x, y, w, h, c, rx=0, rot=None):
    t = f' transform="rotate({rot[0]} {rot[1]} {rot[2]})"' if rot else ''
    r = f' rx="{rx}"' if rx else ''
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}"{r} fill="{c}"{t}/>'
def C(cx, cy, r, c): return f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="{c}"/>'
def P(d, c): return f'<path d="{d}" fill="{c}"/>'
def E(cx, cy, rx, ry, c): return f'<ellipse cx="{cx}" cy="{cy}" rx="{rx}" ry="{ry}" fill="{c}"/>'
G = lambda c=L: R(0, 84, 96, 6, c)   # 바닥선 — 옆 타일과 이어진다
T = {}
# ── 섬: 가장자리에 닿지 않는다 (아이콘·격자) ──
T['b-01'] = ('서류', [R(20, 10, 56, 76, M, 4), R(26, 16, 44, 64, BG, 2), R(32, 24, 32, 4, D), R(32, 34, 32, 4, Pa), R(32, 44, 32, 4, Pa), R(32, 54, 20, 4, Pa), C(58, 68, 7, L)])
T['b-02'] = ('도장', [R(40, 10, 16, 34, D, 8), R(30, 40, 36, 14, M, 4), R(24, 54, 48, 10, D, 3), E(48, 80, 26, 6, Pa), C(48, 80, 3, L)])
T['b-03'] = ('관청', [R(46, 8, 4, 22, D), P('M50 8 L68 14 L50 20 Z', L), R(14, 30, 68, 8, M, 2), R(18, 38, 60, 44, D), R(26, 46, 10, 12, BG), R(43, 46, 10, 12, BG), R(60, 46, 10, 12, BG), R(42, 64, 12, 18, Pa), R(10, 82, 76, 6, M, 2)])
T['b-04'] = ('법원', [P('M48 10 L86 32 L10 32 Z', D), R(14, 32, 68, 6, M), R(20, 40, 8, 36, M), R(36, 40, 8, 36, M), R(52, 40, 8, 36, M), R(68, 40, 8, 36, M), R(12, 76, 72, 6, D), R(8, 82, 80, 6, M, 2), C(48, 23, 4, Pa)])
T['b-05'] = ('등기부', [R(14, 14, 68, 70, D, 4), R(20, 14, 6, 70, M), R(30, 22, 46, 54, BG, 2), R(36, 30, 34, 4, M), R(36, 40, 34, 4, Pa), R(36, 50, 34, 4, Pa), R(36, 60, 22, 4, Pa)])
T['b-06'] = ('펜', [R(42, 8, 12, 52, D, 3, (38, 48, 48)), P('M22 62 L34 74 L16 80 Z', M), R(58, 14, 12, 10, L, 2, (38, 48, 48)), R(14, 84, 44, 4, Pa, 2)])
T['b-07'] = ('두루마리', [R(22, 20, 52, 56, Pa), R(14, 14, 68, 12, D, 6), R(14, 70, 68, 12, D, 6), C(14, 20, 6, M), C(82, 20, 6, M), C(14, 76, 6, M), C(82, 76, 6, M), R(30, 34, 36, 4, D), R(30, 44, 36, 4, M), R(30, 54, 24, 4, M)])
T['b-08'] = ('돋보기', [C(40, 40, 28, D), C(40, 40, 20, BG), R(34, 30, 16, 4, Pa), R(34, 38, 16, 4, Pa), R(34, 46, 10, 4, Pa), R(60, 54, 12, 34, M, 5, (-45, 66, 60))])
T['b-09'] = ('달력', [R(12, 18, 72, 68, D, 5), R(18, 34, 60, 46, BG, 2), R(26, 10, 8, 16, M, 3), R(62, 10, 8, 16, M, 3), R(24, 40, 10, 8, Pa), R(38, 40, 10, 8, Pa), R(52, 40, 10, 8, Pa), R(66, 40, 8, 8, Pa), R(24, 54, 10, 8, Pa), R(38, 54, 10, 8, L), R(52, 54, 10, 8, Pa), R(66, 54, 8, 8, Pa), R(24, 68, 10, 8, Pa), R(38, 68, 10, 8, Pa)])
T['b-10'] = ('봉투', [R(10, 24, 76, 52, D, 4), P('M10 28 L48 56 L86 28 L86 24 L10 24 Z', M), P('M14 72 L40 50 L48 56 L56 50 L82 72 Z', Pa), C(70, 66, 8, L)])
T['b-11'] = ('확인', [P('M48 8 L82 20 L82 48 Q82 74 48 88 Q14 74 14 48 L14 20 Z', D), P('M30 48 L42 60 L66 34 L72 40 L42 72 L24 54 Z', Pa)])
T['b-12'] = ('저울', [R(46, 12, 4, 66, D), R(18, 20, 60, 4, M, 2), C(48, 14, 6, M), P('M12 50 A14 14 0 0 0 40 50 Z', D), P('M56 50 A14 14 0 0 0 84 50 Z', D), P('M26 24 L14 50 L38 50 Z', Pa), P('M70 24 L58 50 L82 50 Z', Pa), R(30, 78, 36, 8, M, 3)])
T['b-13'] = ('집', [P('M48 12 L88 46 L8 46 Z', D), R(18, 46, 60, 38, M), R(40, 58, 16, 26, BG), R(24, 52, 10, 10, Pa), R(62, 52, 10, 10, Pa), R(64, 18, 8, 16, D)])
T['b-14'] = ('가게', [P('M10 30 L18 12 L78 12 L86 30 Z', D), P('M10 30 A9.5 9.5 0 0 0 29 30 Z', L), P('M29 30 A9.5 9.5 0 0 0 48 30 Z', Pa), P('M48 30 A9.5 9.5 0 0 0 67 30 Z', L), P('M67 30 A9.5 9.5 0 0 0 86 30 Z', Pa), R(16, 40, 64, 44, M), R(24, 50, 22, 18, BG), R(54, 50, 18, 34, D), R(10, 84, 76, 4, D, 2)])
T['b-15'] = ('모임', [C(24, 34, 10, M), C(72, 34, 10, M), C(48, 28, 12, D), P('M8 78 Q8 50 24 50 Q36 50 38 62 L38 78 Z', M), P('M88 78 Q88 50 72 50 Q60 50 58 62 L58 78 Z', M), P('M28 84 Q28 46 48 46 Q68 46 68 84 Z', D)])
T['b-16'] = ('사건철', [P('M10 24 L10 16 Q10 12 14 12 L38 12 L46 22 L82 22 Q86 22 86 26 L86 30 L10 30 Z', M), R(10, 28, 76, 54, D, 4), R(20, 40, 40, 4, Pa), R(20, 50, 56, 4, Pa), R(20, 60, 30, 4, Pa), C(72, 68, 6, L)])
# ── 이음: 선과 바닥이 좌우 끝까지 나가 옆 타일과 이어진다 (프리즈) ──
T['b-21'] = ('창구 줄', [G(), R(10, 46, 22, 38, M, 2), R(14, 52, 14, 3, BG), R(14, 59, 14, 3, BG), R(38, 36, 22, 48, D, 2), R(42, 42, 14, 3, Pa), R(42, 49, 14, 3, Pa), R(42, 56, 9, 3, Pa), R(66, 52, 22, 32, M, 2), R(70, 58, 14, 3, BG), R(70, 65, 9, 3, BG)])
T['b-22'] = ('절차', [R(0, 44, 96, 8, Pa), C(48, 48, 16, D), C(48, 48, 7, BG), G()])
T['b-23'] = ('도장 줄', [G(), R(18, 34, 12, 26, D, 6), R(12, 58, 24, 10, M, 3), R(8, 68, 32, 8, D, 2), R(58, 44, 12, 18, M, 6), R(54, 60, 20, 8, D, 3), R(50, 68, 28, 8, M, 2), C(84, 80, 4, Pa)])
T['b-24'] = ('기둥', [R(0, 20, 96, 8, D), R(0, 28, 96, 4, M), R(14, 32, 12, 48, M), R(42, 32, 12, 48, M), R(70, 32, 12, 48, M), R(0, 80, 96, 4, D), G()])
os.makedirs(os.path.join(HERE, 'tiles'), exist_ok=True)
syms = []
for tid, (name, parts) in T.items():
    body = f'<rect width="96" height="96" fill="{BG}"/>' + ''.join(parts)
    off = {c.upper() for c in re.findall(r'#[0-9A-Fa-f]{6}', body)} - PAL
    assert not off, (tid, off)
    open(os.path.join(HERE, 'tiles', f'{tid}.svg'), 'w').write(
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 96" width="96" height="96"><title>{name}</title>{body}</svg>\n')
    syms.append(f'<symbol id="{tid}" viewBox="0 0 96 96"><title>{name}</title>{body}</symbol>')
open(os.path.join(HERE, 'tiles.svg'), 'w').write('<svg xmlns="http://www.w3.org/2000/svg" style="display:none">\n' + '\n'.join(syms) + '\n</svg>\n')
print(len(T), '장')
